import {all,get,put,remove,saveAttempt,uuid,exportData,openDB} from './store.js';
import {profiles,activities,metrics} from './data.js';
import {prepareOffline,verifyOffline,requestPersistence} from './offline.js';
import {guidePoints,evaluateTrace} from './scoring.js';
const $=s=>document.querySelector(s);const escape=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const paths={home:'M3 10 12 3l9 7v10a1 1 0 0 1-1 1h-5v-7H9v7H4a1 1 0 0 1-1-1Z',book:'M12 5v16M3 4q5-2 9 1 4-3 9-1v15q-5-2-9 2-4-4-9-2Z',chart:'M4 20V9m8 11V4m8 16v-7M2 21h20',parents:'M15 21v-3a5 5 0 0 0-10 0v3M10 11a4 4 0 1 0 0-8 4 4 0 0 0 0 8M18 4a3 3 0 0 1 0 6m0 4q4 1 4 6',settings:'M12 8a4 4 0 1 0 0 8 4 4 0 0 0 0-8M12 2v3m0 14v3M2 12h3m14 0h3M5 5l2 2m10 10 2 2M5 19l2-2M17 7l2-2',arrow:'M5 12h14m-5-5 5 5-5 5',back:'M19 12H5m5-5-5 5 5 5',download:'M12 3v12m-5-5 5 5 5-5M4 16v5h16v-5',upload:'M12 16V3m-5 5 5-5 5 5M4 16v5h16v-5',sound:'M11 4 5 9H2v6h3l6 5ZM16 8a6 6 0 0 1 0 8m3-11a10 10 0 0 1 0 14',close:'m5 5 14 14M5 19 19 5',check:'m4 12 5 5L20 6',cloud:'M6 18h12a4 4 0 0 0 0-8 6 6 0 0 0-11-2 5 5 0 0 0-1 10',clock:'M12 8v5l3 2M12 2a10 10 0 1 0 0 20 10 10 0 0 0 0-20',spark:'m12 2 3 7 7 3-7 3-3 7-3-7-7-3 7-3Z',plus:'M12 4v16M4 12h16',file:'M6 2h8l5 5v15H6ZM14 2v6h5M9 12h7m-7 4h7'};
function icon(name){return `<svg class="icon" viewBox="0 0 24 24" aria-hidden="true"><path d="${paths[name]||paths.spark}"/></svg>`}
let page='home',childId='demo-luna',filter='all',attempts=[],lessons=[],materials=[],settings={sound:true,motion:true},offlineReady=false,offlineBusy=false,modalCleanup=null,practice=null,lastFocus;
function child(){return profiles.find(p=>p.id===childId)||profiles[0]}
function available(){return [...activities,...lessons.filter(l=>l.assignedTo.includes(childId))]}
function toast(message){$('#toast').textContent=message;$('#toast').classList.add('show');clearTimeout(toast.t);toast.t=setTimeout(()=>$('#toast').classList.remove('show'),5000)}
function profilePicker(){return `<div class="profiles">${profiles.map(p=>`<button class="profile ${p.id===childId?'active':''}" data-child="${p.id}" aria-pressed="${p.id===childId}"><span class="avatar ${p.color}">${p.emoji}</span><span><strong>${p.name}</strong><small>Perfil de ejemplo</small></span></button>`).join('')}<span class="profile-hint">Cada descubrimiento, a su ritmo.</span></div>`}
function heading(title,sub,eyebrow='UN POQUITO CADA DÍA'){return `<div class="page-heading"><div><div class="eyebrow">${eyebrow}</div><h1>${title}</h1><p class="subtitle">${sub}</p></div></div>`}
function shell(content){const names={home:'Mi inicio',activities:'Mis actividades',progress:'Mis avances',parents:'Para padres',settings:'Configuración',practice:'A practicar'};$('#app').innerHTML=`<div class="prototype-ribbon">Prototipo privado · Perfiles ficticios · Datos guardados solo en este navegador · Firebase e IA pendientes</div><div class="app-shell"><aside class="sidebar"><div class="brand"><img src="./assets/icon.svg" alt=""><span>Aprende<span>.</span></span></div><div class="nav-caption eyebrow">MI PEQUEÑO MUNDO</div><nav class="nav" aria-label="Navegación principal">${[['home','home','Mi inicio'],['activities','book','Mis actividades'],['progress','chart','Mis avances'],['parents','parents','Para padres'],['settings','settings','Configuración']].map(([id,ico,label])=>`<button data-page="${id}" class="${page===id?'active':''}" ${page===id?'aria-current="page"':''}>${icon(ico)}${label}</button>`).join('')}</nav><div class="sidebar-bottom"><div class="offline-sidebar"><div class="eyebrow">${offlineReady?'PAQUETE VERIFICADO':'APRENDE DONDE QUIERAS'}</div><p>${offlineReady?'Los recursos de ejemplo están guardados en este navegador.':'Prepara tus actividades para seguir explorando sin internet.'}</p><button data-offline ${offlineBusy?'disabled':''}>${icon('download')}${offlineBusy?'Verificando…':offlineReady?'Ver mis descargas':'Preparar sin conexión'}</button></div><div class="family"><span class="avatar">🏡</span><div><strong>Familia de ejemplo</strong><span>Espacio de demostración</span></div></div></div></aside><main class="main"><header class="topbar"><div class="crumb">Tu espacio <span> / </span><strong>${names[page]}</strong></div><div class="mobile-brand"><img src="./assets/icon.svg" alt="">Aprende.</div><div class="top-actions"><span class="pill demo-hide">Pequeños pasos, grandes logros</span><span class="pill"><span class="dot ${navigator.onLine?'':'gray'}"></span>${navigator.onLine?'Con conexión':'Sin conexión'} · local</span><button class="icon-btn" data-action="sound" aria-label="${settings.sound?'Desactivar':'Activar'} sonidos" title="Sonidos ${settings.sound?'activados':'desactivados'}">${icon('sound')}</button><span class="top-avatar" aria-label="Perfil ${child().name}">${child().emoji}</span></div></header>${content}<footer class="footer-note"><span>Hecho para aprender a tu ritmo, con alguien a tu lado.</span><span>Aprende · Prototipo 0.1 · Sin servicios cloud activos</span></footer></main></div>`;document.body.classList.toggle('reduce-motion',!settings.motion);bindShell()}
function bindShell(){document.querySelectorAll('[data-page]').forEach(b=>b.onclick=()=>navigate(b.dataset.page));document.querySelectorAll('[data-child]').forEach(b=>b.onclick=async()=>{childId=b.dataset.child;await put('meta',{id:'profile',value:childId});render()});document.querySelectorAll('[data-offline]').forEach(b=>b.onclick=()=>offlineReady?downloadDialog():downloadPack());document.querySelectorAll('[data-action="sound"]').forEach(b=>b.onclick=async()=>{settings.sound=!settings.sound;await saveSettings();toast(settings.sound?'Sonidos activados':'Sonidos desactivados')})}
function card(a){const complete=attempts.some(x=>x.childId===childId&&x.activityId===a.id);return `<article class="activity-card"><div class="card-art ${a.color||'peach'}"><span class="art-type">${escape(a.art||'Aa')}</span><span class="art-status">${complete?'✓ Ya exploraste':a.category==='source'?'Tarea del libro':'Juego de refuerzo'}</span></div><div class="card-body"><div class="card-tag">${escape(a.tag||'Creación familiar')}${['guided','free'].includes(a.type)?'<span>✎ TÁCTIL</span>':''}</div><h3>${escape(a.title)}</h3><p>${escape(a.subtitle||'Creada y aprobada en este navegador')}</p><div class="card-footer"><span>${['guided','free'].includes(a.type)?'Dedo o lápiz':'Toca o haz clic'} · ${a.category==='source'?'Practicar':'Descubrir'}</span><span class="circle-arrow">${icon('arrow')}</span></div></div><button class="card-hit" data-activity="${escape(a.id)}" aria-label="Abrir ${escape(a.title)}"></button></article>`}
function bindCards(){document.querySelectorAll('[data-activity]').forEach(b=>b.onclick=()=>startActivity(b.dataset.activity));document.querySelectorAll('[data-filter]').forEach(b=>b.onclick=()=>{filter=b.dataset.filter;render()})}
function home(){shell(`${heading(`¡Hola, ${child().name}! <span style="font-size:.75em">☀️</span>`,'Hoy es un buen día para descubrir algo nuevo.')}${profilePicker()}<section class="hero" style="margin-top:26px"><div class="hero-copy"><div class="eyebrow">TU AVENTURA COMIENZA AQUÍ</div><h2>Pequeñas letras.<br>Grandes descubrimientos.</h2><p>Un ratito para leer, crear y aprender.<br>¿Qué descubrimos juntos hoy?</p><button class="btn" id="start-first">Vamos a practicar ${icon('arrow')}</button></div><img src="./assets/garden.svg" alt="Un libro sonriente acompañado de letras y plantas"></section><div class="section-head"><h2>Un mundo para explorar</h2><button class="small-link" data-page="activities">Ver todas ${icon('arrow')}</button></div><div class="grid">${available().slice(0,6).map(card).join('')}</div><div class="bottom-banner"><span class="banner-icon">${icon('parents')}</span><div><h3>Su libro también puede ser una aventura</h3><p>Prepara una tarea, revísala y acompaña cada paso.</p></div><button class="btn secondary small" data-page="parents">Espacio para padres ${icon('arrow')}</button></div>`);$('#start-first').onclick=()=>startActivity('letter-m');bindCards();bindShell()}
function activityPage(){const filtered=available().filter(a=>filter==='all'||a.category===filter);shell(`${heading('Aventuras para aprender','Una actividad a la vez. Tú eliges por dónde empezar.','LEER · JUGAR · ESCRIBIR')}${profilePicker()}<div class="tabs" style="margin-top:25px">${[['all','Todas'],['source','Tareas del libro'],['reinforcement','Juegos de refuerzo']].map(([id,t])=>`<button class="tab ${filter===id?'active':''}" data-filter="${id}">${t}</button>`).join('')}</div><div class="grid">${filtered.map(card).join('')}</div><div class="notice" style="margin-top:22px">Las actividades del libro son ejemplos sintéticos. Las tareas que añadas manualmente se muestran aquí al aprobarlas. El trazado requiere pantalla táctil; en PC puedes leer, asociar y completar.</div>`);bindCards()}
function progressPage(){const m=metrics(attempts,childId);const rows=attempts.filter(a=>a.childId===childId).sort((a,b)=>b.createdAt.localeCompare(a.createdAt));shell(`${heading('Cada paso cuenta','Lo que has practicado, guardado aquí mismo.','TUS PEQUEÑOS LOGROS')}${profilePicker()}<div class="stats" style="margin-top:24px"><div class="stat"><span>Intentos guardados</span><strong>${m.count}</strong><small>Solo este navegador</small></div><div class="stat"><span>Actividades exploradas</span><strong>${m.completed}</strong><small>Sin comparar con otros niños</small></div><div class="stat"><span>Tiempo en actividad</span><strong>${Math.round(m.activeMs/60000)}<small> min</small></strong><small>Ventana visible; no mide atención</small></div></div><div class="panel"><div class="section-head" style="margin-top:0"><h2>Mi recorrido</h2><span class="tag">${rows.length} registros reales</span></div>${rows.length?`<div class="table-scroll"><table><thead><tr><th>Actividad</th><th>Modalidad</th><th>Resultado</th><th>Guardado</th></tr></thead><tbody>${rows.map(a=>`<tr><td>${escape(a.title)}<small>${new Date(a.createdAt).toLocaleString('es-DO',{month:'short',day:'numeric',hour:'2-digit',minute:'2-digit'})}</small></td><td>${escape(a.mode==='guided'?'Con guía':a.mode==='free'?'Sin guía':'Reconocimiento')}<small>${escape(a.inputMethod==='pen'?'Lápiz':a.inputMethod==='touch'?'Dedo':a.inputMethod==='mouse'?'Ratón/teclado':'Entrada no identificada')}</small></td><td>${a.score===null?'Práctica sin nota':`${a.score}/10`}<small>${a.experimental?'Estimación experimental':a.evaluationStatus==='practice_only'?'Evaluación pendiente':'Respuesta del ejercicio'}</small></td><td><span class="tag">Solo local</span></td></tr>`).join('')}</tbody></table></div>`:`<div class="empty"><div class="empty-icon">🌱</div><h3>Tu recorrido está por comenzar</h3><p>Completa una actividad y aquí aparecerá tu primer paso. No hay prisa.</p><button class="btn" data-page="activities" style="margin-top:22px">Explorar actividades ${icon('arrow')}</button></div>`}</div><div class="grid" style="grid-template-columns:1fr 1fr"><div class="panel"><h3>Con guía</h3><p>${m.guided.length} intentos. Las notas de trazado son experimentales y se conservan aparte de las otras actividades.</p></div><div class="panel"><h3>Sin guía</h3><p>${m.free.length} prácticas sin puntuación. El reconocimiento de escritura aún necesita validación.</p></div></div><div class="notice">No hay sincronización Firebase activa. ${rows.length} intentos de este perfil están en la cola local. Los informes de IA todavía no se generan; estas cifras se calculan a partir de tu práctica real.</div>`);bindShell()}
function parentsPage(){shell(`${heading('Acompaña sus descubrimientos','Del libro a la práctica, siempre con tu revisión.','ESPACIO PARA PADRES')}<div class="notice info">Esta versión trabaja con ejemplos y archivos locales. Puedes probar el editor manual; las fotos no se envían a ningún servidor. Utiliza material ficticio y evita datos personales de niños.</div><div class="section-head"><h2>Materiales y tareas</h2><button class="btn small" id="new-material">${icon('plus')} Añadir fotos</button></div><div class="panel"><label class="upload-box" for="photo-upload">${icon('upload')}<strong>Una página, nuevas posibilidades</strong><small>Selecciona varias imágenes JPG, PNG o WebP · máximo 5 MB por imagen</small><input id="photo-upload" type="file" accept="image/jpeg,image/png,image/webp" multiple></label><div class="resource-small">Análisis de IA: pendiente de configuración. La revisión de esta versión se realiza manualmente. HEIC no admitido: exporta la foto como JPG.</div></div>${materials.length?`<div class="materials-grid" id="materials">${materials.map((m,i)=>`<article class="material"><img id="photo-${i}" alt="Vista local de la página ${i+1}"><strong>${escape(m.name)}</strong><small>${Math.round(m.size/1024)} KB · Solo local</small><button class="btn secondary small" data-review="${escape(m.id)}">Revisar y crear tarea</button><button class="small-link" data-remove="${escape(m.id)}" style="margin-top:10px">Retirar imagen</button></article>`).join('')}</div>`:''}<div class="panel" style="margin-top:22px"><div class="section-head" style="margin-top:0"><h2>Prueba el flujo completo</h2><span class="badge-demo">Fuente sintética</span></div><div class="editor-source"><div class="book-title">Mi cuaderno · Página de ejemplo</div><h3 style="margin-top:10px">Conocemos la letra M</h3><p>Selecciona la letra M entre estas letras:</p><div style="font-size:31px;letter-spacing:25px;color:#899175">M S L</div></div><button class="btn secondary" id="review-example">Revisar ejemplo y asignar ${icon('arrow')}</button></div><div class="panel"><h3>Tareas aprobadas aquí</h3>${lessons.length?lessons.map(l=>`<div class="settings-row"><div><strong>${escape(l.title)}</strong><small>${l.category==='source'?'Tarea del libro':'Refuerzo'} · Revisión ${l.revision} · ${l.assignedTo.map(id=>profiles.find(p=>p.id===id)?.name).join(', ')}</small></div><span class="tag">Aprobada localmente</span></div>`).join(''):'<p>Aún no hay tareas creadas por ti. Revisa el ejemplo para publicar tu primera actividad local.</p>'}</div><div class="bottom-banner"><span class="banner-icon">${icon('chart')}</span><div><h3>Un resumen basado en lo que ocurre</h3><p>Consulta intentos y modalidades por perfil. IA narrativa aún no conectada.</p></div><button class="btn secondary small" data-page="progress">Ver resultados ${icon('arrow')}</button></div>`);$('#new-material').onclick=()=>$('#photo-upload').click();$('#photo-upload').onchange=e=>addPhotos(e.target.files);$('#review-example').onclick=()=>reviewMaterial(null);materials.forEach((m,i)=>{const url=URL.createObjectURL(m.blob);const img=$(`#photo-${i}`);img.src=url;img.onload=()=>URL.revokeObjectURL(url)});document.querySelectorAll('[data-review]').forEach(b=>b.onclick=()=>reviewMaterial(b.dataset.review));document.querySelectorAll('[data-remove]').forEach(b=>b.onclick=()=>confirmRemove(b.dataset.remove));bindShell()}
async function addPhotos(files){let ok=0;for(const f of [...files].slice(0,20)){if(!['image/jpeg','image/png','image/webp'].includes(f.type)||f.size>5*1024*1024){toast('Solo JPG, PNG o WebP de hasta 5 MB por imagen.');continue}try{const bitmap=await createImageBitmap(f);bitmap.close();await put('materials',{id:uuid(),name:f.name,size:f.size,blob:f,createdAt:new Date().toISOString()});ok++}catch{toast('No se pudo abrir o guardar una imagen. Comprueba el formato y el espacio.')}}materials=await all('materials');render();if(ok)toast(`${ok} imagen${ok>1?'es':''} guardada${ok>1?'s':''} en este navegador. No se enviaron a la nube.`)}
function modal(title,body,actions=''){lastFocus=document.activeElement;$('#modal-root').innerHTML=`<div class="modal-overlay"><section class="modal" role="dialog" aria-modal="true" aria-labelledby="dialog-title" tabindex="-1"><div class="modal-head"><h2 id="dialog-title">${title}</h2><button class="icon-btn" id="modal-close" aria-label="Cerrar">${icon('close')}</button></div>${body}${actions?`<div class="modal-actions">${actions}</div>`:''}</section></div>`;$('#modal-close').onclick=closeModal;$('.modal-overlay').onclick=e=>{if(e.target===$('.modal-overlay'))closeModal()};$('.modal').focus();$('.modal').onkeydown=e=>{if(e.key==='Escape')closeModal();if(e.key==='Tab'){const els=[...$('.modal').querySelectorAll('button:not([disabled]),input,textarea,select,a[href]')];if(e.shiftKey&&document.activeElement===els[0]){e.preventDefault();els.at(-1)?.focus()}else if(!e.shiftKey&&document.activeElement===els.at(-1)){e.preventDefault();els[0]?.focus()}}}}
function closeModal(){modalCleanup?.();modalCleanup=null;$('#modal-root').innerHTML='';lastFocus?.focus?.()}
function confirmRemove(id){modal('Retirar esta imagen',`<p class="subtitle">Se quitará la copia local de la imagen. Las tareas aprobadas y sus resultados permanecerán.</p>`,`<button class="btn secondary" id="cancel-remove">Conservar</button><button class="btn" id="confirm-remove">Retirar imagen</button>`);$('#cancel-remove').onclick=closeModal;$('#confirm-remove').onclick=async()=>{await remove('materials',id);materials=await all('materials');closeModal();render();toast('Imagen local retirada.')};}
function reviewMaterial(id){const mat=materials.find(m=>m.id===id);modal('Revisar antes de compartir',`${mat?'<img class="source-photo" id="review-photo" alt="Página fuente local">':'<div class="editor-source"><div class="book-title">Fuente ficticia revisable</div><p>Selecciona la letra M entre M, S y L.</p></div>'}<div class="notice">Editor manual: la IA no ha leído esta página. Comprueba que la consigna y la respuesta correspondan al contenido antes de aprobar.</div><label class="field"><span>Nombre de la tarea</span><input id="edit-title" maxlength="70" value="${mat?'Mi tarea del libro':'Conocemos la letra M'}"></label><label class="field"><span>Consigna para el niño</span><textarea id="edit-prompt" maxlength="300">${mat?'':'¿Cuál de estas letras es la M?'}</textarea></label><div class="form-grid"><label class="field"><span>Tres opciones, separadas por coma</span><input id="edit-options" maxlength="100" value="${mat?'':'M, S, L'}" placeholder="M, S, L"></label><label class="field"><span>Respuesta correcta exacta</span><input id="edit-answer" maxlength="40" value="${mat?'':'M'}"></label></div><label class="field"><span>Relación con el libro</span><select id="edit-category"><option value="source">Tarea del libro: conserva objetivo y respuesta</option><option value="reinforcement">Juego de refuerzo: una actividad complementaria</option></select></label><p style="font-size:12px;margin-bottom:10px">Asignar a:</p>${profiles.map(p=>`<label class="check"><input type="checkbox" name="assign" value="${p.id}" checked>${p.emoji} ${p.name} (ejemplo)</label>`).join('')}<label class="check" style="margin-top:20px"><input id="review-confirm" type="checkbox">He revisado la consigna y la respuesta.</label><div id="editor-error" role="alert" class="warning-text"></div><p class="resource-small">Motor inicial: selección entre opciones. Las fotos quedan locales. El editor no reproduce automáticamente trazos o ejercicios no compatibles.</p>`,`<button class="btn secondary" id="cancel-review">Cancelar</button><button class="btn" id="approve-lesson">Aprobar y asignar ${icon('check')}</button>`);if(mat){const url=URL.createObjectURL(mat.blob);$('#review-photo').src=url;modalCleanup=()=>URL.revokeObjectURL(url)}$('#cancel-review').onclick=closeModal;$('#approve-lesson').onclick=async()=>{const title=$('#edit-title').value.trim(),prompt=$('#edit-prompt').value.trim(),opts=$('#edit-options').value.split(',').map(x=>x.trim()).filter(Boolean),answer=$('#edit-answer').value.trim(),assignedTo=[...document.querySelectorAll('[name="assign"]:checked')].map(x=>x.value);if(!title||!prompt||opts.length!==3||new Set(opts).size!==3||!opts.includes(answer)||!assignedTo.length||!$('#review-confirm').checked){$('#editor-error').textContent='Completa título y consigna, tres opciones distintas, una respuesta válida, al menos un perfil y la revisión.';return}$('#approve-lesson').disabled=true;try{await put('lessons',{id:uuid(),type:'select',title,prompt,options:opts,answer,assignedTo,category:$('#edit-category').value,revision:1,approvedAt:new Date().toISOString(),sourceId:id||'synthetic-example',art:opts[0].slice(0,4),color:'peach',tag:'Tarea revisada',skill:'Selección manual revisada'});lessons=await all('lessons');closeModal();render();toast('Tarea aprobada y asignada localmente. Ya aparece en las actividades.')}catch(e){$('#editor-error').textContent='No se pudo guardar. Comprueba el almacenamiento.';$('#approve-lesson').disabled=false}}}
function settingsPage(){shell(`${heading('Todo a tu ritmo','Pequeños ajustes para una experiencia más cómoda.','TU ESPACIO')}<div class="panel"><h3>Mientras practicamos</h3><div class="settings-row"><div><strong>Sonidos de celebración</strong><small>Sonidos breves guardados con la aplicación.</small></div><button class="toggle ${settings.sound?'on':''}" id="sound-toggle" role="switch" aria-checked="${settings.sound}" aria-label="Sonidos de celebración"></button></div><div class="settings-row"><div><strong>Animaciones suaves</strong><small>Puedes desactivarlas. También respetamos la preferencia del dispositivo.</small></div><button class="toggle ${settings.motion?'on':''}" id="motion-toggle" role="switch" aria-checked="${settings.motion}" aria-label="Animaciones suaves"></button></div></div><div class="panel"><h3>En este dispositivo</h3><div class="status-list"><div class="status-item"><span class="status-symbol">${offlineReady?'✓':'○'}</span><span>${offlineReady?'Recursos del paquete verificados en caché.':'Modo offline aún no verificado.'}</span></div><div class="status-item"><span class="status-symbol">✓</span><span>IndexedDB: intentos y tareas guardados localmente.</span></div><div class="status-item"><span class="status-symbol">○</span><span>Firebase e IA: pendientes de configurar. No hay sincronización.</span></div><div class="status-item"><span class="status-symbol">○</span><span>Fire 7, iPhone y iPad: pendientes de pruebas físicas.</span></div></div><div style="display:flex;gap:10px;flex-wrap:wrap;margin-top:22px"><button class="btn green" data-offline>${icon('download')}${offlineReady?'Ver descargas':'Preparar sin conexión'}</button><button class="btn secondary" id="export-data">Exportar mis resultados</button></div><p class="resource-small">Borrar los datos del navegador elimina las tareas y resultados locales. El navegador también puede liberar almacenamiento. Exporta una copia si necesitas conservarlos.</p></div><div class="panel"><h3>Acerca de este prototipo</h3><p>Nombre provisional: Aprende. Esta versión privada permite probar el flujo local y la interacción. Los perfiles son ficticios; no hay cuentas de familia autenticadas ni aislamiento multiusuario de producción.</p><p style="margin-top:12px">El trazado con guía usa una estimación técnica experimental. La escritura libre se guarda sin nota. No se emiten diagnósticos ni informes inventados.</p><p class="resource-small">Voz de consignas: usa la voz del navegador si está disponible; no se garantiza offline. El paquete incluye sonidos de refuerzo. Audios hablados descargables quedan pendientes para el producto completo.</p></div>`);$('#sound-toggle').onclick=async()=>{settings.sound=!settings.sound;await saveSettings();render()};$('#motion-toggle').onclick=async()=>{settings.motion=!settings.motion;await saveSettings();render()};$('#export-data').onclick=exportResults;bindShell()}
async function saveSettings(){await put('meta',{id:'settings',value:settings});document.body.classList.toggle('reduce-motion',!settings.motion)}
async function exportResults(){const data=await exportData();const blob=new Blob([JSON.stringify(data,null,2)],{type:'application/json'});const url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download='aprende-resultados-locales.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1500);toast('Copia local de resultados preparada.');}
async function downloadPack(){if(offlineBusy)return;if(page==='practice')return toast('Vuelve a tus actividades antes de preparar una descarga.');offlineBusy=true;render();try{await prepareOffline();offlineReady=await verifyOffline();toast(offlineReady?'Recursos verificados. Prueba cerrar y reabrir sin conexión.':'No fue posible verificar el paquete.');if(offlineReady)downloadDialog()}catch(e){toast(e.message)}finally{offlineBusy=false;render()}}
function downloadDialog(){modal('Tu mochila sin internet',`<div class="notice info">Recursos de aplicación y actividades sintéticas verificados en este navegador. Las tareas que crees y tus intentos se guardan en IndexedDB.</div><div class="status-list"><div class="status-item">✓ Ejercicios, ilustraciones y motor de trazado</div><div class="status-item">✓ Sonidos breves de celebración</div><div class="status-item">✓ Guardado local de intentos y tareas manuales</div><div class="status-item">○ Voz hablada offline aún pendiente</div><div class="status-item">○ Sincronización de resultados aún no conectada</div></div><p class="resource-small">La primera apertura y la descarga necesitan internet. No se ha certificado reapertura offline en Fire 7 o iOS. El almacenamiento puede ser eliminado por el usuario o navegador; no es una copia de seguridad.</p>`,`<button class="btn secondary" id="persist-data">Solicitar conservación</button><button class="btn" id="close-download">Entendido</button>`);$('#close-download').onclick=closeModal;$('#persist-data').onclick=async()=>{const persisted=await requestPersistence();toast(persisted?'El navegador concedió almacenamiento persistente.':'El navegador no concedió persistencia. Puedes seguir usando la app.')}}
function navigate(next){if(practice&&page==='practice'){practice=null;window.speechSynthesis?.cancel()}page=next;filter='all';render();window.scrollTo({top:0,behavior:'instant'})}
function render(){({home,activities:activityPage,progress:progressPage,parents:parentsPage,settings:settingsPage,practice:renderPractice}[page]||home)()}
function startActivity(id){const activity=available().find(a=>a.id===id);if(!activity)return;practice={activity,strokes:[],inputMethods:new Set(),startedAt:performance.now(),activeSince:performance.now(),activeMs:0,saved:false,busy:false,selected:null,pairs:new Set(),wrongPairs:0};page='practice';renderPractice();window.scrollTo(0,0)}
function renderPractice(){if(!practice){page='activities';return render()}const a=practice.activity;const draw=['guided','free'].includes(a.type);shell(`<div class="practice-wrap"><div class="practice-top"><button class="btn secondary small" id="exit-practice">${icon('back')} Mis actividades</button><span class="pill">${child().emoji} ${child().name} · ${a.category==='source'?'Tarea del libro':'Refuerzo'}</span></div><section class="practice-stage"><div class="eyebrow">${escape(a.tag||'ACTIVIDAD FAMILIAR')}</div><h2>${escape(a.title)}</h2><p class="practice-prompt">${escape(a.prompt)}</p><button class="small-link" id="listen" style="margin:0 auto">${icon('sound')} Escuchar consigna <span style="font-size:9px;font-weight:400">(voz del navegador)</span></button>${a.type==='complete'?`<div class="big-word">${escape(a.prefix||'')}<span class="gap">?</span>${escape(a.suffix||'')}</div>`:''}${a.type==='read'?`<div class="story" style="margin-top:25px">${escape(a.story)}</div>`:''}${a.options?`<div class="letter-options">${a.options.map(o=>`<button class="option ${o.length>2?'word':''}" data-answer="${escape(o)}">${escape(o)}</button>`).join('')}</div>`:''}${a.type==='match'?`<div class="matches"><div class="match-col">${a.pairs.map(p=>`<button class="match-btn" data-word="${escape(p.word)}">${escape(p.word)}</button>`).join('')}</div><div class="match-col">${[...a.pairs].reverse().map(p=>`<button class="match-btn" data-image="${escape(p.word)}" aria-label="Dibujo: ${escape(p.word)}">${p.image}</button>`).join('')}</div></div><p class="warning-text" id="match-hint">Elige una palabra y después el dibujo correspondiente.</p>`:''}${draw?`<div class="notice" style="margin-top:18px;text-align:left">${a.type==='guided'?'Estimación experimental: compara el recorrido, no certifica aprendizaje.':'Práctica libre sin nota: el reconocimiento automático no está validado.'} Solo dedo o lápiz táctil.</div><div class="canvas-wrap"><canvas id="trace-canvas" width="600" height="500" aria-label="Área para escribir ${escape(a.symbol)} con dedo o lápiz"></canvas><span class="canvas-label">${a.type==='guided'?'Repasa la guía con calma':'Tu espacio para escribir'}</span></div><p id="input-warning" class="warning-text" style="margin-top:12px">En computadora sin pantalla táctil, prueba las otras actividades.</p><div class="practice-tools"><button class="btn secondary small" id="clear-trace">Empezar de nuevo</button><button class="btn green" id="finish-trace">Terminé ${icon('check')}</button></div>`:''}<div id="practice-result" aria-live="polite"></div></section><p class="resource-small" style="text-align:center">Un adulto debe acompañar si la voz no está disponible. Se guardan los intentos terminados; una actividad sin terminar se pierde al salir o recargar.</p></div>`);$('#exit-practice').onclick=()=>navigate('activities');$('#listen').onclick=()=>{if(!('speechSynthesis'in window))return toast('La voz no está disponible. Pide a un adulto que lea la consigna.');const utterance=new SpeechSynthesisUtterance(a.prompt);utterance.lang='es-DO';utterance.rate=.85;speechSynthesis.cancel();speechSynthesis.speak(utterance);toast('La voz depende del navegador; no forma parte del paquete offline.')};document.querySelectorAll('[data-answer]').forEach(b=>b.onclick=()=>finishChoice(b.dataset.answer));if(a.type==='match')bindMatch();if(draw)bindCanvas()}
function chime(){if(!settings.sound)return;const audio=new Audio('./assets/success.wav');audio.volume=.25;audio.play().catch(()=>{})}
function pauseClock(){if(practice?.activeSince){practice.activeMs+=Math.max(0,performance.now()-practice.activeSince);practice.activeSince=null}}
function resumeClock(){if(practice&&!practice.activeSince&&!document.hidden)practice.activeSince=performance.now()}
async function persistResult(result){if(!practice||practice.saved||practice.busy)return false;const session=practice;const owner=childId;session.busy=true;pauseClock();const a=session.activity;const method=session.inputMethods.size>1?'mixed':[...session.inputMethods][0]||'unknown';const attempt={id:uuid(),childId:owner,familyId:'demo-local-family',activityId:a.id,title:a.title,activityRevision:a.revision||1,mode:a.type==='guided'?'guided':a.type==='free'?'free':'recognition',inputMethod:method,createdAt:new Date().toISOString(),visibleDurationMs:Math.round(session.activeMs),score:result.score,evaluationStatus:result.evaluationStatus,experimental:!!result.experimental,components:result.components||null,scoringVersion:result.scoringVersion||'choice-v1',syncStatus:'awaiting_backend'};try{await saveAttempt(attempt);attempts.push(attempt);session.saved=true;return practice===session&&page==='practice'}catch{toast('No se pudo guardar. Comprueba el espacio y vuelve a intentar.');session.busy=false;if(practice===session)resumeClock();return false}}
async function finishChoice(answer){if(practice.saved||practice.busy)return;const correct=answer===practice.activity.answer;if(await persistResult({score:correct?10:0,evaluationStatus:'scored'})){document.querySelectorAll('[data-answer]').forEach(b=>{b.disabled=true;if(b.dataset.answer===answer)b.classList.add('selected')});showResult(correct?'¡Lo encontraste!':'Vamos a descubrirlo juntos',correct?10:0,correct?'Tu respuesta coincide con la del ejercicio.':`La respuesta de esta actividad es «${practice.activity.answer}». Puedes probar otra vez.`)}}
function showResult(title,score,note){chime();$('#practice-result').innerHTML=`<div class="result"><div style="font-size:30px">${score===null?'🌱':score>=7?'✨':'🌼'}</div><h3>${escape(title)}</h3>${score!==null?`<div class="score">${score}<span style="font-size:20px;color:#a2af92"> / 10</span></div>`:''}<p>${escape(note)}</p><div class="local-status">✓ Intento guardado en este navegador</div><div class="result-actions"><button class="btn secondary" id="try-again">Practicar otra vez</button><button class="btn green" id="next-activity">Seguir explorando ${icon('arrow')}</button></div></div>`;$('#try-again').onclick=()=>startActivity(practice.activity.id);$('#next-activity').onclick=()=>navigate('activities');$('#practice-result').scrollIntoView({behavior:settings.motion?'smooth':'instant',block:'nearest'})}
function bindMatch(){document.querySelectorAll('[data-word]').forEach(b=>b.onclick=()=>{if(practice.saved||practice.pairs.has(b.dataset.word))return;practice.selected=b.dataset.word;document.querySelectorAll('[data-word]').forEach(x=>x.classList.toggle('selected',x===b))});document.querySelectorAll('[data-image]').forEach(b=>b.onclick=async()=>{if(practice.saved||practice.busy||practice.pairs.has(b.dataset.image))return;if(!practice.selected)return toast('Primero elige una palabra.');if(b.dataset.image!==practice.selected){practice.wrongPairs++;$('#match-hint').textContent='Mira la palabra y prueba con otro dibujo.';return}practice.pairs.add(practice.selected);const w=document.querySelector(`[data-word="${practice.selected}"]`);w.classList.remove('selected');w.classList.add('matched');b.classList.add('matched');w.disabled=true;b.disabled=true;practice.selected=null;$('#match-hint').textContent='¡Una pareja encontrada! Vamos con otra.';if(practice.pairs.size===practice.activity.pairs.length){const score=practice.wrongPairs?Math.max(1,Math.round(10*practice.pairs.size/(practice.pairs.size+practice.wrongPairs))):10;const session=practice;if(await persistResult({score,evaluationStatus:'scored'}))showResult('¡Todas las parejas juntas!',score,'Nota del ejercicio: parejas correctas respecto a todos los intentos de asociación.');else if(practice===session&&!session.saved){session.pairs.delete(b.dataset.image);w.disabled=false;b.disabled=false;w.classList.remove('matched');b.classList.remove('matched');$('#match-hint').textContent='No se guardó todavía. Vuelve a unir esta última pareja para reintentar.'}}})}
function bindCanvas(){const canvas=$('#trace-canvas'),ctx=canvas.getContext('2d');let current=null,pointerId=null;const a=practice.activity;function paint(){ctx.clearRect(0,0,600,500);ctx.strokeStyle='#eee9da';ctx.lineWidth=1;for(const y of [100,250,400]){ctx.beginPath();ctx.moveTo(20,y);ctx.lineTo(580,y);ctx.stroke()}if(a.type==='guided'){const pts=guidePoints(a.symbol);ctx.setLineDash([5,11]);ctx.strokeStyle='#c5ccb4';ctx.lineWidth=14;ctx.lineCap='round';ctx.beginPath();pts.forEach((p,i)=>i?ctx.lineTo(p.x*600,p.y*500):ctx.moveTo(p.x*600,p.y*500));ctx.stroke();ctx.setLineDash([]);if(pts[0]){ctx.fillStyle='#b2c197';ctx.beginPath();ctx.arc(pts[0].x*600,pts[0].y*500,10,0,Math.PI*2);ctx.fill()}}ctx.strokeStyle='#e37c55';ctx.lineWidth=9;ctx.lineJoin='round';ctx.lineCap='round';for(const stroke of practice.strokes){ctx.beginPath();stroke.forEach((p,i)=>i?ctx.lineTo(p.x*600,p.y*500):ctx.moveTo(p.x*600,p.y*500));ctx.stroke()}}
const point=e=>{const r=canvas.getBoundingClientRect();return {x:Math.max(0,Math.min(1,(e.clientX-r.left)/r.width)),y:Math.max(0,Math.min(1,(e.clientY-r.top)/r.height))}};canvas.onpointerdown=e=>{if(practice.saved||practice.busy)return;if(!['touch','pen'].includes(e.pointerType)){$('#input-warning').textContent='El ratón no se evalúa. Usa tu dedo o lápiz en una pantalla táctil, o elige otra actividad.';return}if(pointerId!==null)return;e.preventDefault();pointerId=e.pointerId;canvas.setPointerCapture(pointerId);practice.inputMethods.add(e.pointerType);current=[point(e)];practice.strokes.push(current);$('#input-warning').textContent=e.pointerType==='pen'?'Entrada: lápiz táctil':'Entrada: dedo';paint()};canvas.onpointermove=e=>{if(e.pointerId!==pointerId||!current)return;e.preventDefault();if(current.length<3000)current.push(point(e));requestAnimationFrame(paint)};canvas.onpointerup=e=>{if(e.pointerId!==pointerId)return;current=null;pointerId=null;paint()};canvas.onpointercancel=()=>{current=null;pointerId=null;$('#input-warning').textContent='El trazo se interrumpió. Puedes continuarlo o empezar de nuevo.'};$('#clear-trace').onclick=()=>{if(practice.saved)return;practice.strokes=[];practice.inputMethods.clear();paint()};$('#finish-trace').onclick=async()=>{if(practice.saved||practice.busy)return;if(!practice.strokes.some(s=>s.length>2))return toast('Haz un trazo con tu dedo o lápiz antes de terminar.');const method=practice.inputMethods.size>1?'mixed':[...practice.inputMethods][0]||'unknown';if(a.type==='free'){if(await persistResult({score:null,evaluationStatus:'practice_only'}))showResult('¡Has practicado a tu manera!',null,'Escritura libre guardada sin nota. Todavía no evaluamos automáticamente su forma.');return}const raw=evaluateTrace(practice.strokes,a.symbol,method);const result={...raw,evaluationStatus:raw.score===null?'not_evaluable':'scored',experimental:true};if(await persistResult(result))showResult(raw.score===null?'Podemos volver a intentarlo':'¡Tu recorrido está guardado!',raw.score,raw.score===null?'No hay una evaluación válida para este intento. No se asignó una nota.':'Estimación experimental de cercanía y cobertura de la guía. No es una evaluación validada del aprendizaje.');};paint()}
document.addEventListener('visibilitychange',()=>document.hidden?pauseClock():resumeClock());window.addEventListener('offline',()=>{if(page!=='practice')render();toast('Sin internet: puedes continuar con lo preparado en este navegador.')});window.addEventListener('online',()=>{if(page!=='practice')render();toast('Conexión disponible. La sincronización Firebase todavía no está configurada.')});
async function init(){try{await openDB();[attempts,lessons,materials]=await Promise.all([all('attempts'),all('lessons'),all('materials')]);const s=await get('meta','settings');if(s)settings=s.value;const p=await get('meta','profile');if(profiles.some(x=>x.id===p?.value))childId=p.value;home();offlineReady=await verifyOffline();if(page!=='practice')render()}catch(e){$('#app').innerHTML=`<div class="initial-loader" style="padding:35px"><div>Necesitamos guardar tu práctica</div><span>Este navegador no permitió abrir el almacenamiento local. Usa una ventana normal y comprueba que tenga espacio disponible.</span><button class="btn" id="retry-storage">Volver a intentar</button></div>`;$('#retry-storage').onclick=()=>location.reload()}}
init();
